class RemoteConnection(object):

    def __init__(self):
        self.config = ConfigHandler.get_config()
        self.controller = Controller()
        self.tunnel = None

    @check_rat
    def setup_remote_access(self, **kwargs):
        """
        This method has been modified to handled 'ute_fsmaccess' and to support existing usage
        under 'lib/oam/admin/counters/datetime_operations.py/DatetimeOperations
        class/get_currenttime_on_enb(..)
        If you are using this method to handle SSH or Telnet sessions. Make sure
        "session_type' is updated. To avoid error consider to use "create_session_with_host"
        method instead.

        @param kwargs: connection details to the host
            remote_device: string, remote device name as specified in `testline_config.json`
            timeout: int, execution timeout. Default '10'
            alias: string, Execution context. Default 'default'
        @return:
        @raise
            From Telnet library : Exception
            From SSH library : SSHException
            UTE FSM : Exception from ute_fsmaccess library
        """
        remote_device = kwargs["remote_device"]
        timeout = kwargs.get("timeout", 10)
        alias = kwargs.get("alias", 'default')
        host_details = RemoteConnection().get_host_details(remote_device)

        # Adding port to host_details to support port change option while connecting.
        # This was part of ute_fsmaccess library
        if kwargs.get("port"):
            host_details['port'] = kwargs['port']

        host_details.update(kwargs)
        RemoteConnection._key_generation_and_upload(host_details)
        logger.info("creating session with {0}".format(remote_device))
        if not host_details['session_type']:
            host_details['session_type'] = self._get_session_type(remote_device)
        logger.info("Host Details are  {0}".format(host_details))
        self.controller.create_session_with_host(host_details, alias, timeout)
        logger.info("session created with {0}\nAssociated with alias {1}".format(remote_device,
                                                                                 alias))

    @check_rat
    def remote_command_execute(self, **kwargs):
        """
        This method is used to execute remote command on the session created during
        'setup_remote_access' using alias.

        This keyword will execute only 'ute_fsmaccess' related API's.
        This keyword is deprecated to use fro SSH or Telnet sessions.

        Consider using execute_remote_command instead.

        @param kwargs: connection details to the host
            continue_on_failure: string, remote device to be referred from `testline_config.json`
            command_section: command section to be referred from `testline_config.json`.
                Default None.
            command: Command to execute. Mandatory, if 'command_section' is not specified.
            return_rc: bool, Flag for returning shell command rc. Default: False.
            alias: string, Execution context. Default 'default'
            pty: boolean, True or False
        @return: string, Source file path.
        @raise
            Key-Error
        """
        self.continue_on_failure = kwargs.get("continue_on_failure", True)
        alias = kwargs.get('alias', 'default')
        if kwargs.get("command_section"):
            commands_list = get_config_var(["remote_commands"] + kwargs["command_section"].split("."))
            return self._remote_command_execute_and_verify(commands_list, alias)
        else:
            command = kwargs["command"]
            return_rc = kwargs.get("return_rc", False)
            pty = kwargs.get("pty", False)
            return self._remote_command_execution_without_verification(command=command, return_rc=return_rc,
                                                                       alias=alias, pty=pty)

