    def get_host_details(self, remote_device):
        """
        This method will get the host details of the given parameter from the testline_config.
        @param remote_device: dict, remote device details
        @return: dictionary containing host details fetched from testline_config file
        @raise
            Key-error
        """
        host_details = {}
        if remote_device is not None:
            host_details = self._get_remote_location_credentials_from_remote_device(remote_device)
        RemoteConnection._validate_mandatory_arguments(host_details)
        return host_details

    def get_file(self, source, destination, alias='default'):
        """
            Gets the file from given source as specified by the alias to destination on the local
            machine.
            @param source: string, source path
            @param destination: string, destination path
            @param alias: string, Execution context. Default 'default'
            @return: string, Destination path.
            @raise Exception raised from ute_fsmaccess library
        """
        logger.info("Obtaining file from {0} to {1}".format(source, destination))
        filename = self.controller.get_file_from_host(source=source, destination=destination,
                                                      alias=alias)
        logger.info("File obtained")
        return filename

    def put_file(self, source, destination, alias='default'):
        """
            Copies the file from given source on the local machine to destination path on the host
            specified by alias
            @param source: string, source path
            @param destination: string, destination path
            @param alias: string, Execution context. Default 'default'
            @return: string, Source file path.
            @raise Exception raised from ute_fsmaccess library
        """
        logger.info("Transferring file from {0} to {1}".format(source, destination))
        self.controller.put_file_on_host(source=source, destination=destination, alias=alias)
        logger.info("File transferred")

    def create_ssh_tunnel(self, remote_ip, remote_port, remote_user, remote_pwd, remote_bind_ip,
                          remote_bind_port, local_bind_ip, local_bind_port):
        """
        This method creates a ssh tunnel between the given parameters
        @param remote_ip: string, remote device ip
        @param remote_port: int, remote device port
        @param remote_user: string, remote device username
        @param remote_pwd: string, remote device password
        @param remote_bind_ip: string, ip to bind the remote device
        @param remote_bind_port: int, port to bind the remote device
        @param local_bind_ip: string, local bind ip
        @param local_bind_port: int, local bind port
        @return:
        @raise: SSHTunnelException
        """
        self.tunnel = SSHTunnelForwarder((remote_ip, remote_port), ssh_username=remote_user,
                                         ssh_password=remote_pwd,
                                         remote_bind_address=(remote_bind_ip, remote_bind_port),
                                         local_bind_address=(local_bind_ip, local_bind_port))
        self.tunnel.start()

    def stop_ssh_tunnel(self):
        """
        This method stops the tunnel created
        @return:
        @raise: SSHTunnelException
        """
        if self.tunnel is not None:
            self.tunnel.stop()

    def connect_to_hop(self, **kwargs):
        """
        Connect to hop
        @param kwargs:
            remote_device: string, command to execute.
            alias: string, Execution context.
            session_type: string, type of connection ssh/sftp to perform on given remote device
            prompt: string, send expected prompt. Default '$'.
        @return: None
        @raise 	SSHException, Exception: raises an exception
        """
        remote_device = kwargs['remote_device']
        alias = kwargs.get('alias', 'default')
        session_type = kwargs.get('session_type', 'ssh')
        prompt = kwargs.get('prompt', get_config_var([remote_device, 'prompt'])) or '$'

        password = get_config_var([remote_device, 'password'])
        username = get_config_var([remote_device, 'user'])
        ip = get_config_var([remote_device, 'ip'])
        cmd = "{0} {1}@{2}".format(session_type, username, ip)

        return self.controller.connect_to_hop(command=cmd, password=password, prompt=prompt, alias=alias)

    def execute_command_on_shell(self, **kwargs):
        """
            This method Executes given command on the shell session type (SSH) specified by alias.
            Currently supported for SSH session types only
            @param kwargs:
                command: string, command to execute
                alias: string, Execution context
                exit_prompt: string, if exit_prompt is given keyword waits untill exit prompt is seen in output.
                If exit_prompt is not passed, keyword just returns the command output
                timeout: int, execution timeout. Default 10
            @return: response received from the corresponding session/channel
            @raise 	SSHException: raises an exception
        """
        timeout = kwargs.get('timeout', 10)
        alias = kwargs.get('alias', 'default')
        command = kwargs['command']
        exit_prompt = kwargs.get('exit_prompt', None)
        return_rc = kwargs.get('return_rc', False)
        return self.controller.execute_command_on_shell(command=command, alias=alias, exit_prompt=exit_prompt,
                                                        timeout=timeout, return_rc=return_rc)

    def exit_hop_connection(self, alias):
        """
            This method exits from the SSH connection specified by alias. This is most used to exit
            multiple/double ssh connections by specifying its alias created during setup method.
            @param alias: string, Execution context.
            @return:
            @raise
                From SSH library : SSHException
        """
        return self.controller.exit_from_hop_connection(alias)

    @check_rat
    def teardown_remote_access(self, alias='default'):
        """
        Teardown remote access
        @param alias: string, Execution context. Default 'default'.
        @return:
        @raise
            From Telnet library : Exception
            From SSH library : SSHException
            UTE FSM : Exception from ute_fsmaccess library
        """
        logger.info("Terminating connection associated with {0}".format(alias))
        self.controller.close_session_with_host(alias)
        logger.info("Terminated connection associated with {0}".format(alias))

    @staticmethod
    def _validate_mandatory_arguments(host_details):
        if host_details.get('ip') is None or host_details.get('user') is None or (
                        host_details.get('password') is None and host_details.get('private_key') is None):
            BuiltIn().fail(
                "One of the mandatory arguments host/user/password/private_key is not present {}/{}/{}/{}!!".format(
                    host_details.get('ip'), host_details.get('user'),
                    host_details.get(
                        'password'), host_details.get('private_key')))

    def _get_remote_location_credentials_from_remote_device(self, profile_section):
        host_details = {}
        if not isinstance(profile_section, list):
            profile_section = profile_section.split(".")
        host_details["ip"] = get_config_var(profile_section + ["ip"])
        host_details["user"] = get_config_var(profile_section + ["user"])
        host_details["password"] = get_config_var(profile_section + ["password"])
        host_details["prompt"] = get_config_var(profile_section + ["prompt"])
        host_details["port"] = get_config_var(profile_section + ["port"])
        host_details["private_key"] = get_config_var(profile_section + ["private_key"])
        host_details["session_type"] = get_config_var(profile_section + ["session_type"]) or get_config_var(
            profile_section + ["connection_type"])
        host_details["remote_host"] = get_config_var(profile_section + ['remote_lmp_ip'])
        host_details["remote_ssh_user"] = get_config_var(profile_section + ["remote_lmp_user"])
        host_details["remote_ssh_pass"] = get_config_var(profile_section + ["remote_lmp_password"])
        host_details["remote_ssh_prompt"] = get_config_var(profile_section + ["remote_lmp_ssh_prompt"])
        host_details["root_user"] = get_config_var(profile_section + ["root_user"])
        host_details["root_password"] = get_config_var(profile_section + ["root_password"])
        host_details["root_private_key"] = get_config_var(profile_section + ["root_private_key"])

        logger.info("Host details collected \n{0}".format(str(host_details)))
        return host_details

    def _get_session_type(self, remote_device):
        # if "cbts" in remote_device:
        #     return 'SSH'
        # return 'FSM'
        return 'SSH'

    # <editor-fold desc="All methods in this fold are retrained to support existing implementation
    # of RemoteConnection class">
    @staticmethod
    def _key_generation_and_upload(host_details):
        try:
            user_public_key, root_public_key = None, None
            if host_details.get('private_key') and host_details.get('root_private_key'):
                user_public_key = SshController.keygen_write_to_file(
                    host_details.get('private_key'))
                root_public_key = SshController.keygen_write_to_file(
                    host_details.get('root_private_key'))
            elif host_details.get('root_private_key'):
                root_public_key = SshController.keygen_write_to_file(
                    host_details.get('root_private_key'))
            elif host_details.get('private_key'):
                root_public_key = SshController.keygen_write_to_file(
                    host_details.get('private_key'))
            if user_public_key is not None or root_public_key is not None:
                SshController.upload_keys_to_remote_host(host_details, public_key=user_public_key,
                                                         root_user_public_key=root_public_key)
            logger.info("SSH Keys generated successfully and copied to remote host")
        except Exception as key_gen_exception:
            BuiltIn().fail(
                "SSH Key Generation or copying keys failed due to {}".format(key_gen_exception))

    @staticmethod
    def _delete_key_file(private_key, root_private_key):
        if private_key:
            os.remove(private_key)
        if root_private_key:
            os.remove(root_private_key)

    def _remote_command_execution_without_verification(self, command, return_rc, alias, pty):
        return self.controller.execute_command_on_host(command=command, return_rc=return_rc, alias=alias, pty=pty)

    def _remote_command_execute_and_verify(self, commands_list, alias):
        logger.debug("Command details after variable substitution is {}".format(commands_list))
        result = self._execute_commands_on_remote_location_and_get_result(commands_list, alias)
        self._verify_command_output_status(result)
        return result

    def _execute_commands_on_remote_location_and_get_result(self, commands_list, alias):
        call_function_for_get_value = {True: self._get_expected_result_from_dict,
                                       False: self._ret_none}
        commands_results = []
        for command in commands_list:
            command_dict = {}
            logger.debug("Instance of command is {}".format(isinstance(command, dict)))
            command_dict['command'] = self._get_command_based_on_instance(command)
            command_dict['expected_result'] = call_function_for_get_value.get(
                isinstance(command, dict))(command)
            command_dict['alias'] = alias
            self._execute_commands_on_remote_location_and_verify(command_dict)
            logger.debug("command_result_dict is {}".format(command_dict))
            commands_results.append({command_dict['command']: command_dict})
            logger.debug("command_result_list is {}".format(commands_results))
        return commands_results

    def _get_command_based_on_instance(self, command):
        call_function_for_get_command = {True: self._get_command_from_dict,
                                         False: self._ret_command}
        return call_function_for_get_command.get(isinstance(command, dict))(command)

    def _get_command_from_dict(self, command):
        return list(command.keys())[0]

    def _get_expected_result_from_dict(self, command):
        return list(command.values())[0]

    def _ret_none(self, command):
        return None

    def _ret_command(self, command):
        return command

    def _execute_commands_on_remote_location_and_verify(self, command_dict):
        output = self.controller.execute_command_on_host(command=command_dict['command'], return_rc=True,
                                                         alias=command_dict['alias'], pty=False)
        command_dict['obtained_result'], command_dict[
            'status'] = self._get_result_and_status_from_output(output)
        self._verify_status_of_command_execution_and_output(command_dict)

    def _get_result_and_status_from_output(self, obtained_cmd_result_and_status):
        if not isinstance(obtained_cmd_result_and_status, tuple):
            return obtained_cmd_result_and_status, 0
        else:
            return obtained_cmd_result_and_status[0], obtained_cmd_result_and_status[1]

    def _verify_status_of_command_execution_and_output(self, command_dict):
        if command_dict['status'] != 0:
            log_string = "{0} :: Command execution returned with status ({1}).\n" \
                         "Obtained output :: {2}".format(command_dict['command'],
                                                         command_dict['status'],
                                                         command_dict['obtained_result'])
            if self.continue_on_failure:
                logger.warn(log_string)
                command_dict['status'] = "FAIL"
            else:
                BuiltIn().fail(log_string)
        else:
            return self._verify_output_result(command_dict)

    def _verify_output_result(self, command_dict):
        if command_dict.get("status", "PASS") != "FAIL" and command_dict.get('expected_result') \
                is not None and command_dict.get('expected_result') != '':
            return self._is_expected_output_present_in_output(command_dict)
        else:
            return command_dict.get("status")

    def _is_expected_output_present_in_output(self, command_dict):
        if bool(re.search(command_dict["expected_result"], command_dict["obtained_result"],
                          re.MULTILINE)):
            command_dict['status'] = "PASS"
        else:
            if self.continue_on_failure:
                command_dict['status'] = "FAIL"
            else:
                BuiltIn().fail(
                    "{0} :: Command verification failed\n"
                    "Expected result::{1}\n"
                    "Obtained result::{2}".format(command_dict["command"],
                                                  command_dict["expected_result"],
                                                  command_dict["obtained_result"]))

    def _verify_command_output_status(self, result):
        self._display_final_result(result)
        for command_dict in result:
            if "FAIL" == list(command_dict.values())[0].get("status", "PASS"):
                BuiltIn().fail("Fail ::  Command execution failed for {}".format(command_dict))

    def _display_final_result(self, result):
        for command_dict in result:
            command = list(command_dict.keys())[0]
            logger.info("Command :: {0}\n"
                        "Status :: {1}\n"
                        "Expected Result :: {2}\n"
                        "Obtained Result ::\n{3}".format(command,
                                                         command_dict[command]["status"],
                                                         command_dict[command]["expected_result"],
                                                         command_dict[command]["obtained_result"]))

    # </editor-fold>
